  }
  FILTER NOT EXISTS {
    GRAPH ?g {
      ?birth rdf:type sphn:Birth .
      ?birth sphn:hasDeliveryModeCode ?birth_code .
      ?birth_code rdf:type <http://snomed.info/id/129106006> OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
  }
}

